// #8140c180a9bf2e83d1a17783 — в таблице «תמיכה ותפעול» (/admin/support) при 1440 имя, начинающееся
// с латиницы, видно с начала и обрезается в конце с «…». Кейс SUP-001. Только чтение — @prod-safe.
// (Папка admin-support, а не support: tests/support/ — общие помощники api.ts/session.ts.)
import { test, expect } from '../../fixtures';

type Cell = { col: number; text: string; truncated: boolean; firstVisible: boolean; lastHidden: boolean; textOverflow: string };

test.describe('Поддержка — усечение латинских имён (#8140c180a9bf2e83d1a17783)', () => {
  test('1440: у латинского имени первая буква внутри ячейки, длинное обрезано в конце (ellipsis) @desktop @prod-safe #8140c180a9bf2e83d1a17783', async ({ asUser }) => {
    const page = await asUser('admin');
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto('/admin/support');
    await expect(page.locator('main table tbody tr').first()).toBeVisible();

    // Колонки 0–1 — бизнес и кандидат. Текстовый элемент — первый лист с текстом в ячейке.
    const cells: Cell[] = await page.evaluate(() => {
      const out: Cell[] = [];
      document.querySelectorAll('main table tbody tr').forEach((tr) => {
        [0, 1].forEach((col) => {
          const td = tr.querySelectorAll('td')[col];
          if (!td) return;
          const el = [td, ...td.querySelectorAll('*')].find(
            (e) => e.children.length === 0 && (e as HTMLElement).innerText?.trim(),
          ) as HTMLElement | undefined;
          if (!el) return;
          const tn = [...el.childNodes].find((n) => n.nodeType === 3 && n.textContent!.trim()) as Text | undefined;
          if (!tn) return;
          const s = tn.textContent!;
          const fi = s.search(/\S/);
          if (!/[A-Za-z]/.test(s[fi])) return; // только имена, начинающиеся с латиницы
          const er = el.getBoundingClientRect();
          const tdr = td.getBoundingClientRect();
          const rg = document.createRange();
          rg.setStart(tn, fi);
          rg.setEnd(tn, fi + 1);
          const fr = rg.getBoundingClientRect();
          const li = s.trimEnd().length - 1;
          rg.setStart(tn, li);
          rg.setEnd(tn, li + 1);
          const lr = rg.getBoundingClientRect();
          const inside = (r: DOMRect, box: DOMRect) => r.left >= box.left - 1 && r.right <= box.right + 1;
          out.push({
            col,
            text: s.trim().slice(0, 60),
            truncated: el.scrollWidth > el.clientWidth + 1,
            firstVisible: inside(fr, er) && inside(fr, tdr),
            lastHidden: !inside(lr, er),
            textOverflow: getComputedStyle(el).textOverflow,
          });
        });
      });
      return out;
    });

    expect(cells.length, 'нет имён, начинающихся с латиницы, — нужны данные (QA-… кандидаты/бизнесы)').toBeGreaterThan(0);
    const truncated = cells.filter((c) => c.truncated);
    expect(truncated.length, 'нет ни одного обрезанного латинского имени — нужен длинный (напр. QA-G4b-K3-1357…)').toBeGreaterThan(0);

    // Источник: «מה רצוי» — «שם ארוך נחתך בסופו עם שלוש נקודות, ותחילתו נשארת גלויה בכל כיוון כתב».
    expect(cells.filter((c) => !c.firstVisible).map((c) => c.text), 'начало имени срезано').toEqual([]);
    expect(truncated.filter((c) => c.textOverflow !== 'ellipsis').map((c) => c.text), 'обрезка без «…»').toEqual([]);
    expect(truncated.filter((c) => !c.lastHidden).map((c) => c.text), 'скрыт не конец имени').toEqual([]);
  });
});
